static network_component_event network_component_eventqueue_pop(network_component_eventqueue * eq)
{
	network_component_event event;
	if(network_component_eventqueue_size(eq) <= 0) {
		network_component_event_init(&event, Network_Component_invalid_event);
	}
	else {
		event = eq->events[eq->pop_index];
		
		if(eq->pop_index < eq->capacity - 1) {
			eq->pop_index++;
		} 
		else {
			eq->pop_index = 0;
		}
		eq->size--;
	}
	return event;
}
static sc_boolean network_component_eventqueue_push(network_component_eventqueue * eq, network_component_event ev)
{
	if(network_component_eventqueue_size(eq) == eq->capacity) {
		return bool_false;
	}
	else {
		eq->events[eq->push_index] = ev;
		
		if(eq->push_index < eq->capacity - 1) {
			eq->push_index++;
		}
		else {
			eq->push_index = 0;
		}
		eq->size++;
		
		return bool_true;
	}
}
